def transform(grid):
    H = len(grid)
    W = len(grid[0]) if H > 0 else 0

    # Find background (most common) 
    from collections import Counter
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1
    bg = max(counts, key=counts.get)

    # Find special cell
    special_c = None
    sr, sc = None, None
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg:
                special_c = grid[r][c]
                sr, sc = r, c
                break
        if special_c:
            break

    # Create output filled with background
    output = [[bg for _ in range(W)] for _ in range(H)]

    if special_c is not None:
        # For the special cell's row: checkerboard starting at special column
        for c in range(W):
            if (c - sc) % 2 == 0:
                output[sr][c] = special_c

        # For adjacent rows: checkerboard offset by 1 position
        for dr in [-1, 1]:
            nr = sr + dr
            if 0 <= nr < H:
                for c in range(W):
                    if (c - sc + 1) % 2 == 0:
                        output[nr][c] = special_c

    return output
